export function writeManagedReviewEvidenceProposal(args: {
  root: string;
  runId: string;
  proposal: Omit<ManagedReviewEvidenceProposal, 'schemaVersion' | 'runId' | 'authoredAt'>;
  environment?: NodeJS.ProcessEnv;
